#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define CB_CLOSED 0
#define CB_OPEN 1
#define CB_HALF_OPEN 2
#define CB_FAILURE_THRESHOLD 5
#define CB_TIMEOUT_SEC 30
#define MAX_FONT_NAME 256
#define PDF_BUF_SIZE 4096

typedef struct {
    int state;
    int failure_count;
    time_t last_failure_time;
} circuit_breaker_t;

typedef struct {
    char buffer[PDF_BUF_SIZE];
    size_t offset;
    circuit_breaker_t cb;
} pdf_context_t;

static int cb_allow_request(circuit_breaker_t *cb) {
    if (cb->state == CB_CLOSED) return 1;
    if (cb->state == CB_OPEN) {
        if (time(NULL) - cb->last_failure_time > CB_TIMEOUT_SEC) {
            cb->state = CB_HALF_OPEN;
            return 1;
        }
        return 0;
    }
    return 1; /* HALF_OPEN allows one probe */
}

static void cb_record_success(circuit_breaker_t *cb) {
    cb->failure_count = 0;
    cb->state = CB_CLOSED;
}

static void cb_record_failure(circuit_breaker_t *cb) {
    cb->failure_count++;
    cb->last_failure_time = time(NULL);
    if (cb->failure_count >= CB_FAILURE_THRESHOLD) {
        cb->state = CB_OPEN;
    }
}

/* NFC normalization stub: decomposes then recomposes.
 * In production this would call ICU or similar.
 * Key behavior: certain sequences expand during decomposition.
 */
static size_t normalize_nfc(const uint8_t *input, size_t inlen,
                            uint8_t *output, size_t outmax) {
    size_t j = 0;
    for (size_t i = 0; i < inlen && j < outmax; i++) {
        if (input[i] == 0xC3 && i + 1 < inlen) {
            /* Latin chars with combining: e.g. U+00E9 (C3 A9) -> 'e' + combining acute */
            /* During decomposition phase, one 2-byte sequence becomes 3 bytes */
            if (j + 3 <= outmax) {
                output[j++] = input[i+1] & 0x7F; /* base char approximation */
                output[j++] = 0xCC;               /* combining mark lead */
                output[j++] = 0x81;               /* combining acute accent */
            }
            i++; /* skip continuation byte */
        } else {
            output[j++] = input[i];
        }
    }
    return j;
}

/* Recomposition step: combines base + combining back to precomposed.
 * This is where the vulnerability lives: the length check uses
 * pre-normalization length but writes post-normalization data.
 */
static size_t recompose(const uint8_t *decomposed, size_t declen,
                        uint8_t *output, size_t outmax) {
    size_t j = 0;
    for (size_t i = 0; i < declen && j < outmax; i++) {
        if (i + 2 < declen && decomposed[i+1] == 0xCC && decomposed[i+2] == 0x81) {
            /* Recompose: base + combining acute -> precomposed */
            output[j++] = 0xC3;
            if (j < outmax) output[j++] = decomposed[i] | 0x80;
            i += 2;
        } else {
            output[j++] = decomposed[i];
        }
    }
    return j;
}

static int validate_font_name_length(const uint8_t *name, size_t len) {
    /* Security check: font name must fit in MAX_FONT_NAME.
     * We check the INPUT length before normalization. */
    return len <= MAX_FONT_NAME;
}

int pdf_set_font(pdf_context_t *ctx, const uint8_t *font_name, size_t name_len) {
    if (!cb_allow_request(&ctx->cb)) {
        return -1; /* circuit open, reject */
    }

    /* Length validation on original input */
    if (!validate_font_name_length(font_name, name_len)) {
        cb_record_failure(&ctx->cb);
        return -2;
    }

    /* Normalize the font name (NFC) */
    uint8_t decomposed[MAX_FONT_NAME * 2];
    size_t dec_len = normalize_nfc(font_name, name_len, decomposed, sizeof(decomposed));

    uint8_t normalized[MAX_FONT_NAME];
    /* BUG: recompose uses MAX_FONT_NAME as outmax, but decomposed data
     * can be larger than original input. The recomposition doesn't always
     * shrink back to original size for crafted inputs where combining
     * marks are already present in input (they pass through decompose
     * unchanged, then recompose may not match them). */
    size_t norm_len = recompose(decomposed, dec_len, normalized, MAX_FONT_NAME);

    /* Write PDF font reference - uses norm_len which can exceed buffer expectations */
    char font_ref[512];
    int written = snprintf(font_ref, sizeof(font_ref),
        "/F1 << /Type /Font /BaseFont /%.*s >>\n",
        (int)norm_len, normalized);

    if (written < 0 || ctx->offset + (size_t)written >= PDF_BUF_SIZE) {
        cb_record_failure(&ctx->cb);
        return -3;
    }

    memcpy(ctx->buffer + ctx->offset, font_ref, (size_t)written);
    ctx->offset += (size_t)written;

    cb_record_success(&ctx->cb);
    return 0;
}

/* The exploit: craft input with existing combining sequences that
 * expand during decomposition but DON'T recompose, causing
 * normalized output to exceed MAX_FONT_NAME. The stack buffer
 * 'normalized' overflows. */
int pdf_add_text(pdf_context_t *ctx, const uint8_t *text, size_t text_len,
                 const uint8_t *font_name, size_t font_len) {
    int rc = pdf_set_font(ctx, font_name, font_len);
    if (rc != 0) return rc;

    if (ctx->offset + text_len + 32 >= PDF_BUF_SIZE) {
        cb_record_failure(&ctx->cb);
        return -4;
    }

    int written = snprintf(ctx->buffer + ctx->offset,
        PDF_BUF_SIZE - ctx->offset,
        "BT (%.*s) Tj ET\n", (int)text_len, text);

    if (written > 0) ctx->offset += (size_t)written;
    cb_record_success(&ctx->cb);
    return 0;
}

pdf_context_t* pdf_create(void) {
    pdf_context_t *ctx = calloc(1, sizeof(pdf_context_t));
    if (ctx) {
        ctx->cb.state = CB_CLOSED;
        ctx->cb.failure_count = 0;
        ctx->offset = 0;
    }
    return ctx;
}

void pdf_destroy(pdf_context_t *ctx) {
    free(ctx);
}
